local function P(...) print(pcall(...)) end
local function show(t) local o = {} for i = 1, #t do o[i] = tostring(t[i]) end return table.concat(o, ",") end
P(table.insert, {}, 2, 3, 4) P(table.insert, {}, 5, 1) P(table.insert, {1}, 0, 1) P(table.insert, {}) P(table.insert, 1, 2)
P(table.remove, {}, 5) P(table.remove, {1,2}, 4) P(table.remove, {}, 0) P(table.remove, {}, -1) P(table.remove, {1}, 3) P(table.remove, {1,2,3}) P(table.remove, {1,2,3}, 1) P(table.remove, {1,2,3}, 4)
local t = {1,2,3} table.insert(t, 2, "x") table.insert(t, "y") print(show(t)) table.remove(t, 1) print(show(t))
P(table.concat, 3) P(table.concat, {}, " ", math.maxinteger, math.maxinteger) P(table.concat, {1, {}}) P(table.concat, {1,2,3}, ", ", 2) P(table.concat, {1,2}, 3) P(table.concat, {1.5, "x"}, "-") P(table.concat, {}, "x") P(table.concat, {1,2,3}, "", 3, 2)
P(table.unpack, {}, 0, 2147483647) P(table.unpack, {}, 1, 1e6) P(table.unpack, {1,2,3}) P(table.unpack, {1,2,3}, -1, 1) P(table.unpack, {}, math.maxinteger, math.mininteger)
local a, b = table.unpack({[math.maxinteger] = 20}, math.maxinteger - 1, math.maxinteger) print(a, b)
P(table.move, 1, 2, 3, 4) P(table.move, {}, 0, math.maxinteger, 1) P(table.move, {}, 1, math.maxinteger, 2) P(table.move, {}, math.mininteger, -2, 2) P(table.move, {}, 1, 2, 3, 5)
local m = table.move({1,2,3,4,5}, 2, 4, 1) print(show(m)) m = table.move({1,2,3,4,5}, 1, 3, 3) print(show(m)) m = table.move({1,2,3}, 1, 3, 1, {}) print(show(m)) print(show(table.move({1,2}, 1, 0, 5)))
P(table.create, 2147483648) P(table.create, 0, 2147483648) P(table.create, 0, 2147483647) P(table.create, -1) P(table.create, 3, -1) P(table.create, 1.5) P(table.create)
local c = table.create(100) print(#c) c[1] = 5 print(#c)
P(table.sort, {1, "x"}) P(table.sort, {1,2}, 3) P(table.sort, 5) P(table.sort, {1,2,3,4}, function(a,b) return true end) P(table.sort, {1,0/0,2})
local s = {5, 3, 8, 1, 9, 2, 7, 4, 6, 0} table.sort(s) print(show(s)) table.sort(s, function(a, b) return a > b end) print(show(s))
local w = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"} table.sort(w) print(show(w))
local eq = {} for i = 1, 100 do eq[i] = false end table.sort(eq, function() return nil end) print(#eq)
local mix = {3, 1.5, 2, -1, 2.5, math.huge, -math.huge} table.sort(mix) print(show(mix))
local big = {} for i = 1, 1000 do big[i] = (i * 7919) % 1000 end table.sort(big) local ok = true for i = 2, 1000 do if big[i-1] > big[i] then ok = false end end print(ok, big[1], big[1000])
local cnt = 0 local big2 = {} for i = 1, 1000 do big2[i] = (i * 7919) % 1001 end table.sort(big2, function(a, b) cnt = cnt + 1 return a < b end) print(big2[1], big2[1000])
local p = table.pack(1, nil, 3) print(p.n, p[1], p[2], p[3])
